package com.pharmacy.payment;
import com.pharmacy.common.ApiResponse;import com.pharmacy.security.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Size;
@RestController @RequiredArgsConstructor public class RefundController {private final RefundService service;@PostMapping("/api/user/orders/{orderId}/refunds")public ApiResponse<RefundRecord> request(@PathVariable Long orderId,@Valid @RequestBody Reason r){return ApiResponse.success(service.request(CurrentUser.id(),orderId,r.reason()));}@PostMapping("/api/admin/mock-refunds/callback")public ApiResponse<Void> callback(@Valid @RequestBody Callback r){service.callback(r.refundNo(),r.callbackKey(),r.success());return ApiResponse.success(null);}public record Reason(@NotBlank @Size(max=255) String reason){}public record Callback(@NotBlank String refundNo,@NotBlank @Size(max=80) String callbackKey,boolean success){}}
